test("他の artboard の辺に吸い付いていて、揃え先から離れている間は、揃え先との隙間が出る", () => {
  renderCanvas({ selection: setupSelection() });
  drawnFollowingFrames();

  // `first` の下辺 140 と `second` の上辺 200 の間は 60 空いている
  pressPointer(artboardHandle("second"), { x: 0, y: 0 });
  movePointer(canvasContent(), { x: -29, y: 200 });

  expect(snapGuides()).toHaveLength(1);
  expect(snapGapLabels()).toEqual(["60"]);
});

test("倍率を上げて運んでいる間も、揃え先との隙間はドキュメント上の px で出る", () => {
  renderCanvas({ selection: setupSelection() });
  wheel(canvasSurface(), { x: 0, y: -100 }, "ctrl");

  /*
   * 1.2 倍で見ているときの描かれた矩形（200 × 140 が 240 × 168、左 232 が 278.4）。
   * 動かすのは 1 回だけで、その間は描き直す前の実測が読まれるので固定の矩形でよい。
   */
  drawnAt("first", { left: 0, top: 0, width: 240, height: 168 });
  drawnAt("second", { left: 278.4, top: 0, width: 240, height: 168 });
  drawnAt("third", { left: 556.8, top: 0, width: 240, height: 168 });

  /*
   * 左辺は 242.4 まで来て `first` の右辺 240 へ吸い付き、上辺は 240 まで下がる。`first` の
   * 下辺 168 まで画面上で 72、ドキュメント上で 60。倍率を表示へ渡し忘れると画面上の値（72）が出る。
   */
  pressPointer(artboardHandle("second"), { x: 0, y: 0 });
  movePointer(canvasContent(), { x: -36, y: 240 });

  expect(snapGuides()).toHaveLength(1);
  expect(snapGapLabels()).toEqual(["60"]);
});

test("離すと線は消える", () => {
  renderCanvas({ selection: setupSelection() });
  drawnFollowingFrames();

  pressPointer(artboardHandle("second"), { x: 0, y: 0 });
  movePointer(canvasContent(), { x: -29, y: 30 });
  expect(snapGuides()).toHaveLength(1);
  releasePointer(canvasContent(), { x: -29, y: 30 });

  expect(snapGuides()).toHaveLength(0);
});

test("右辺の帯を兄弟の右辺の近くまで運んでいる間、揃え先との隙間の数値は出ない", () => {
  renderCanvas({ selection: setupSelection(["badge"]) });
  drawnApart();
  const badge = drawnAt("badge", BadgeBounds);

  // `badge` の下辺 120 と `marker` の上辺 160 の間は 40 空いている（移動なら「40」が出る）
  pressPointer(badge, { x: 218, y: 100 });
  movePointer(badge, { x: 258, y: 100 });

  expect(snapGuides()).toHaveLength(1);
  expect(snapGapLabels()).toEqual([]);
});

/**
 * 揃った線に引くガイド線だけを出す。見た目は `SnapGuideOverlay` のガイド線と同じで、揃え先との
 * 隙間の数値は出さない。
 */
export function GuideLineOverlay({ guides }: Readonly<{ guides: SnapGuides }>) {
  return (
    <>
      <GuideLineAlong guides={guides} pair={SidePairs.Horizontal} />
      <GuideLineAlong guides={guides} pair={SidePairs.Vertical} />
    </>
  );
}

/**
 * 揃った線（辺か中心線）に引くガイド線と、揃え先との隙間の数値（docs/06-ui.md「キャンバス
 * 直接操作」の辺のスナップ。色・太さ・数値の単位の選定理由もそちらにある）。どこへ引くかは
 * `side-snap` が実測から決める。
 *
 * 並びを `map` しないので、線の同一性を key で作る必要が無い。
 */
export function SnapGuideOverlay({
  guides,
  view,
}: Readonly<{ guides: SnapGuides; view: CanvasView }>) {
  return (
    <>
      <Guide guides={guides} pair={SidePairs.Horizontal} view={view} />
      <Guide guides={guides} pair={SidePairs.Vertical} view={view} />
    </>
  );
}

/**
 * ある軸の揃え先との隙間を、見せる数値と一緒に引く（docs/06-ui.md の辺のスナップ）。
 *
 * 引くキーと測る向きを同じ `pair` から取る。キーと向きを別々に渡す形にすると、取り違えた
 * ときに線の太さが隙間の数値として出る。
 *
 * @param guides 軸ごとのスマートガイド
 * @param pair 見る軸（揃った線を挟む辺の組）
 * @param view 割り戻しに使う倍率を持つ表示
 * @returns 隙間の短い線と数値。その軸に揃った線が無い / 揃え先と重なっている・接している /
 *   ドキュメント上の px へ丸めると 0 になるなら `none`
 */
toGapReadout(
  guides: SnapGuides,
  pair: SidePair,
  view: CanvasView,
): Option<GapReadout> {
  return Option.flatMap(guides[pair], (guide) =>
    Option.flatMap(guide.gapLine, (gapLine) => {
      const length = CanvasView.toRoundedDocumentLength(
        view,
        Range.length(
          CanvasBounds.extentAlong(gapLine, SidePair.perpendicular(pair)),
        ),
      );
      return length > 0 ? Option.some({ gapLine, length }) : Option.none;
    }),
  );
},
